UPDATE places SET state_name=(SELECT s.state_name FROM cities c JOIN states s ON s.id=c.state_id WHERE c.id=places.city_id),created_at='2026-10-05',updated_at='2026-10-05',verification_status='partial',verification_notes='Official 5A scenic-area identity verified from the Ministry of Culture and Tourism data service; live/provider metadata not fetched.',verified_at='2026-10-05',source='PRC Ministry of Culture and Tourism, National 5A Tourist Attractions data service (dataset date 2025-03-11); identity basis checked 2026-10-05' WHERE id BETWEEN 156000001 AND 156000359;
INSERT INTO opening_hours (id,place_id,notes) SELECT id,id,'Exact weekly hours require official/operator/provider refresh; not guessed.' FROM places WHERE id BETWEEN 156000001 AND 156000359;
INSERT INTO photos (id,place_id,photo_title,usage_terms,thumbnail_url,photo_url,photo_author,photo_license,photo_source_url,photo_status) SELECT id,id,place_name,'no-photo-available',NULL,NULL,NULL,NULL,NULL,'no_match' FROM places WHERE id BETWEEN 156000001 AND 156000359;
INSERT INTO place_tags (place_id,tag_id) SELECT p.id,t.id FROM places p JOIN tags t ON t.tag_name='5A Scenic Area' WHERE p.id BETWEEN 156000001 AND 156000359;
COMMIT;
